import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <mma.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAException.h>
#include <cute/tensor.hpp>

using namespace cute;
using namespace nvcuda;

namespace cute_matmul_detail {

constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 16;
constexpr int THREADS = 256;
constexpr int RM = 8;
constexpr int RN = 8;
constexpr int SPLIT_K = 8;

  constexpr int STAGES = 2;
constexpr int SMEM_B_STRIDE = BN + 1;
__device__ __forceinline__ void cute_cp_async_16(float* dst, const float* src) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;" ::
                 "r"(static_cast<unsigned>(__cvta_generic_to_shared(dst))),
                 "l"(src));
#else
    *reinterpret_cast<float4*>(dst) = *reinterpret_cast<const float4*>(src);
#endif
}

__device__ __forceinline__ void cute_cp_async_commit() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.commit_group;" ::: "memory");
#endif
}

__device__ __forceinline__ void cute_cp_async_wait() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.wait_group 0;" ::: "memory");
#endif
}

__device__ __forceinline__ void cute_load_tile(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ smem_A,
    float* __restrict__ smem_B,
    int tid,
    int block_m,
    int block_n,
    int k_base,
    int k_end,
    int M,
    int N,
    int K,
    bool can_vec_A,
    bool can_vec_B)
{
    for (int linear = tid * 4; linear < BM * BK; linear += THREADS * 4) {
        const int row = linear / BK;
        const int col = linear % BK;
        const int gm = block_m + row;
        const int gk = k_base + col;
        const bool valid_vec =
            can_vec_A &&
            ((reinterpret_cast<uintptr_t>(smem_A + row * BK + col) & 0xF) == 0) &&
            linear + 3 < BM * BK &&
            col + 3 < BK &&
            gm < M &&
            gk + 3 < K &&
            gk + 3 < k_end;
        if (valid_vec) {
            cute_cp_async_16(
                smem_A + row * BK + col,
                A + static_cast<int64_t>(gm) * K + gk);
        } else {
            #pragma unroll
            for (int x = 0; x < 4; ++x) {
                const int local_col = col + x;
                if (local_col < BK) {
                    const int kk = k_base + local_col;
                    smem_A[row * BK + local_col] =
                        (gm < M && kk < K && kk < k_end)
                            ? A[static_cast<int64_t>(gm) * K + kk]
                            : 0.0f;
                }
            }
        }
    }

    for (int linear = tid * 4; linear < BK * BN; linear += THREADS * 4) {
        const int row = linear / BN;
        const int col = linear % BN;
        const int gk = k_base + row;
        const int gn = block_n + col;
        const bool valid_vec =
            can_vec_B &&
            ((reinterpret_cast<uintptr_t>(smem_B + row * SMEM_B_STRIDE + col) & 0xF) == 0) &&
            linear + 3 < BK * BN &&
            col + 3 < BN &&
            gk < K &&
            gk < k_end &&
            gn + 3 < N;
        if (valid_vec) {
            cute_cp_async_16(
                smem_B + row * SMEM_B_STRIDE + col,
                B + static_cast<int64_t>(gk) * N + gn);
        } else {
            #pragma unroll
            for (int x = 0; x < 4; ++x) {
                const int local_col = col + x;
                if (local_col < BN) {
                    const int nn = block_n + local_col;
                    smem_B[row * SMEM_B_STRIDE + local_col] =
                        (gk < K && gk < k_end && nn < N)
                            ? B[static_cast<int64_t>(gk) * N + nn]
                            : 0.0f;
                }
            }
        }
    }
}

__global__ void cute_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ partial,
    int M,
    int N,
    int K)
{
    constexpr int A_STAGE = BM * BK;
    constexpr int B_STAGE = BK * SMEM_B_STRIDE;
    constexpr int C_STAGE = BM * BN;
    extern __shared__ float smem[];
    float* smem_A = smem;
    float* smem_B = smem + A_STAGE;
    const int tid = threadIdx.x;
    const int split = blockIdx.z;
    const int block_m = blockIdx.y * BM;
    const int block_n = blockIdx.x * BN;
    const int k_begin = (K * split) / SPLIT_K;
    const int k_end = (K * (split + 1)) / SPLIT_K;
    const int warp_id = tid / 32;
    const int warp_row = warp_id / 2;
    const int warp_col = warp_id % 2;
    const int lane_id = tid % 32;
    // Each warp covers a 32x64 region. Each thread computes one 8x8
    // FP32 tile, covering the complete 128x128 CTA output tile.
    const int thread_row = lane_id / 8;
    const int thread_col = lane_id % 8;
    const int base_m = warp_row * 32 + thread_row * RM;
    const int base_n = warp_col * 64 + thread_col * RN;
    float accum[RM][RN];
    #pragma unroll
    for (int i = 0; i < RM; ++i) {
        #pragma unroll
        for (int j = 0; j < RN; ++j) {
            accum[i][j] = 0.0f;
        }
    }
    for (int k_base = k_begin; k_base < k_end; k_base += BK) {
        for (int linear = tid; linear < A_STAGE; linear += THREADS) {
            const int row = linear / BK;
            const int col = linear % BK;
            const int gm = block_m + row;
            const int gk = k_base + col;
            smem_A[linear] =
                (gm < M && gk < K && gk < k_end)
                    ? A[static_cast<int64_t>(gm) * K + gk]
                    : 0.0f;
        }
        for (int linear = tid; linear < B_STAGE; linear += THREADS) {
            const int row = linear / SMEM_B_STRIDE;
            const int col = linear % SMEM_B_STRIDE;
            const int gk = k_base + row;
            const int gn = block_n + col;
            smem_B[linear] =
                (col < BN && gk < K && gk < k_end && gn < N)
                    ? B[static_cast<int64_t>(gk) * N + gn]
                    : 0.0f;
        }
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float a_frag[RM];
            #pragma unroll
            for (int i = 0; i < RM; ++i) {
                a_frag[i] = smem_A[(base_m + i) * BK + kk];
            }
            #pragma unroll
            for (int j = 0; j < RN; ++j) {
                const float b_value =
                    smem_B[kk * SMEM_B_STRIDE + base_n + j];
                #pragma unroll
                for (int i = 0; i < RM; ++i) {
                    accum[i][j] = fmaf(a_frag[i], b_value, accum[i][j]);
                }
            }
        }
        __syncthreads();
    }
    float* split_C = partial + static_cast<int64_t>(split) * M * N;
    #pragma unroll
    for (int i = 0; i < RM; ++i) {
        #pragma unroll
        for (int j = 0; j < RN; ++j) {
            const int m = block_m + base_m + i;
            const int n = block_n + base_n + j;
            if (m < M && n < N) {
                split_C[static_cast<int64_t>(m) * N + n] =
                    accum[i][j];
            }
        }
    }
}

__global__ void cute_matmul_reduce_kernel(
    const float* __restrict__ partial,
    float* __restrict__ C,
    int total)
{
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;
    float value = 0.0f;
    #pragma unroll
    for (int split = 0; split < SPLIT_K; ++split) {
        value += partial[static_cast<int64_t>(split) * total + idx];
    }
    C[idx] = value;
}

}  // namespace cute_matmul_detail

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must be 2-dimensional");
    TORCH_CHECK(B.dim() == 2, "B must be 2-dimensional");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");

    const int M = static_cast<int>(A.size(0));
    const int K = static_cast<int>(A.size(1));
    const int K_B = static_cast<int>(B.size(0));
    const int N = static_cast<int>(B.size(1));
    TORCH_CHECK(K == K_B, "Incompatible matrix dimensions");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();
    auto C = torch::empty({M, N}, A.options());
    auto partial = torch::empty({cute_matmul_detail::SPLIT_K, M, N}, A.options());

    dim3 block(cute_matmul_detail::THREADS);
    dim3 grid(
        (N + cute_matmul_detail::BN - 1) / cute_matmul_detail::BN,
        (M + cute_matmul_detail::BM - 1) / cute_matmul_detail::BM,
        cute_matmul_detail::SPLIT_K);

     constexpr size_t shared_bytes =
         (cute_matmul_detail::BM * cute_matmul_detail::BK +
          cute_matmul_detail::BK * cute_matmul_detail::SMEM_B_STRIDE) *
         sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_matmul_detail::cute_matmul_kernel<<<grid, block, shared_bytes, stream>>>(
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        partial.data_ptr<float>(),
        M,
        N,
        K);

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    const int total = M * N;
    dim3 reduce_block(cute_matmul_detail::THREADS);
    dim3 reduce_grid((total + cute_matmul_detail::THREADS - 1) /
                     cute_matmul_detail::THREADS);
    cute_matmul_detail::cute_matmul_reduce_kernel<<<reduce_grid, reduce_block, 0, stream>>>(
        partial.data_ptr<float>(),
        C.data_ptr<float>(),
        total);
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE split-K matrix multiplication launch failed");
    return C;
}
"""


cute_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=[
        "-O3",
        "-std=c++17",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-std=c++17",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

