        (reinterpret_cast<uintptr_t>(A) & 0xF) == 0 && (K % 4 == 0);
    const bool can_vec_B =
        (reinterpret_cast<uintptr_t>(B) & 0xF) == 0 && (N % 4 == 0);

    const int warp_id = tid / 32;
    const int lane = tid & 31;

    float accum[8][8];
    #pragma unroll
    for (int slot = 0; slot < 8; ++slot) {
        #pragma unroll
        for (int value = 0; value < 8; ++value) {
            accum[slot][value] = 0.0f;
        }
    }

    int current_stage = 0;
    float* current = smem + current_stage * STAGE_SIZE;
