        const int next_k = k_base + BK;
        const bool has_next = next_k < k_end;
        const int next_stage = current_stage ^ 1;
        float* next = smem + next_stage * STAGE_SIZE;

        if (has_next) {
            cute_load_tile(
                A, B,
                next,
                next + A_STAGE,
                tid,
                block_m,
                block_n,
                next_k,
                k_end,
                M,
                N,
                K,
                can_vec_A,
                can_vec_B);
            cute_cp_async_commit();
        }

        float* smem_A = current;
        float* smem_B = current + A_STAGE;

        #pragma unroll
        for (int slot = 0; slot < 8; ++slot) {
            const int tile_m = slot;
            const int tile_n = warp_id;
            #pragma unroll
            for (int value = 0; value < 8; ++value) {
                const int linear = lane + value * 32;
                const int local_m = linear / 16;
                const int local_n = linear % 16;
