    #pragma unroll
    for (int slot = 0; slot < 8; ++slot) {
        const int tile_m = slot;
        const int tile_n = warp_id;
        #pragma unroll
        for (int value = 0; value < 8; ++value) {
            const int linear = lane + value * 32;
            const int local_m = linear / 16;
            const int local_n = linear % 16;
            const int m = block_m + tile_m * 16 + local_m;
            const int n = block_n + tile_n * 16 + local_n;
